// Campaign attribution, in about forty lines and with no third party.
//
// Cloudflare Web Analytics gets you half the picture: /go/<campaign>/ pages
// (generated by scripts/build-blog.mjs) each get their own row in the Paths
// report, so you can see which LinkedIn post produced clicks. What it cannot
// see is the other end. The primary CTA is a mailto:, and a mailto: click
// loads no page, fires no beacon, and leaves no trace anywhere.
//
// So the campaign rides along instead. A /go/ page forwards to its
// destination with ?ref=<campaign>; this file stashes that for the session and
// tags the subject line of any mailto: the visitor clicks afterwards. The
// email that lands in the inbox says which note sent it — which is the number
// that actually matters, and it comes from a channel that cannot be blocked,
// sampled, or stripped by a mobile app.

(function () {
  var KEY = 'shezz77:ref'
  // ?ref= arrives from the open web, and it ends up inside an href. Anything
  // that is not a campaign slug is not a campaign.
  var VALID = /^[a-z0-9][a-z0-9-]{0,48}$/
  var ref = null

  try {
    var fromUrl = new URLSearchParams(location.search).get('ref')
    if (fromUrl && VALID.test(fromUrl)) {
      sessionStorage.setItem(KEY, fromUrl)
      // Drop it from the address bar so the visitor never copies a tagged link
      // into a share, and so Cloudflare's Paths row stays clean.
      history.replaceState(null, '', location.pathname + location.hash)
    }
    ref = sessionStorage.getItem(KEY)
  } catch (e) {
    // Private mode, or storage disabled. Attribution is a nicety; the page is not.
  }

  if (!ref || !VALID.test(ref)) return

  // Delegated and in the capture phase: the portfolio re-renders its contact
  // section on every scroll-driven state change, so a listener bound to the
  // anchor itself would not survive.
  document.addEventListener(
    'click',
    function (ev) {
      var el = ev.target
      var a = el && el.closest && el.closest('a[href^="mailto:"]')
      if (!a) return

      var href = a.getAttribute('href')
      if (href.indexOf('%5B') > -1 || href.indexOf('[') > -1) return // already tagged

      var cut = href.indexOf('?')
      var addr = cut === -1 ? href : href.slice(0, cut)
      // The blog's "share by email" button is a recipientless mailto: whose
      // subject is the note's own title. Tagging that would put the campaign
      // in a reader's message to a colleague.
      if (addr.length <= 'mailto:'.length) return
      var query = cut === -1 ? [] : href.slice(cut + 1).split('&')
      var tag = ' [' + ref + ']'
      var tagged = false

      for (var i = 0; i < query.length; i++) {
        if (query[i].slice(0, 8).toLowerCase() === 'subject=') {
          query[i] = query[i] + encodeURIComponent(tag)
          tagged = true
          break
        }
      }
      if (!tagged) query.push('subject=' + encodeURIComponent('Enquiry' + tag))

      a.setAttribute('href', addr + '?' + query.join('&'))
    },
    true,
  )
})()
